package com.nexus.prm.data

import java.io.File
import java.util.Base64
import javax.crypto.AEADBadTagException
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder

class TaggedBackupCompatibilityTest {
  @get:Rule val temp = TemporaryFolder()

  // These portable archives were generated by the tagged v1 LocalDirectoryRepository.exportBackup
  // implementations with synthetic profiles and the test-only password below.
  private val tags = listOf("v1.0.0", "v1.0.4", "v1.0.10", "v1.0.16")
  private val password = "nexus-fixture"

  @Test
  fun taggedArchivesRestoreAndRoundTripWithLegacyFieldsAndLinks() = runTest {
    for (tag in tags) {
      val directory = temp.newFolder()
      val repository = open(directory)
      repository.saveProfile(PersonProfile(id = "replace-me", name = "Local profile"))
      val preview = repository.inspectBackup(archive(tag), password)
      repository.applyBackup(preview)

      val reopened = open(directory)
      assertFixture(tag, reopened)
      val roundTrip = open(temp.newFolder())
      roundTrip.applyBackup(roundTrip.inspectBackup(reopened.exportBackup(password), password))
      assertFixture(tag, roundTrip)
    }
  }

  @Test
  fun taggedArchivesMergeTwiceWithoutDuplicatingOrOverwritingLocalData() = runTest {
    for (tag in tags) {
      val repository = open(temp.newFolder())
      repository.saveProfile(PersonProfile(id = "legacy-person", name = "Edited locally"))
      repository.saveProfile(PersonProfile(id = "local-only", name = "Local only"))
      val preview = repository.inspectBackup(archive(tag), password)

      repeat(2) { repository.applyMergeRestore(preview) }

      assertEquals(tag, setOf("legacy-person", "introducer", "local-only"), repository.profiles.value.map { it.id }.toSet())
      assertEquals(tag, "Edited locally", repository.getProfile("legacy-person")?.name)
      assertFixture(tag, repository, name = "Edited locally", favourite = false)
    }
  }

  @Test
  fun malformedArchivesAndFailedRestoreLeaveDirectoryOnDisk() = runTest {
    val directory = temp.newFolder()
    val repository = open(directory)
    val local = repository.saveProfile(PersonProfile(id = "keep-me", name = "Local profile"))
    val legacy = archive("v1.0.0")
    val snapshot = File(directory, "nexus_directory.enc")
    val original = snapshot.readBytes()

    val wrongPassword = runCatching { repository.inspectBackup(legacy, "wrong-password") }
    assertTrue(wrongPassword.exceptionOrNull() is AEADBadTagException)
    val damaged = legacy.copyOf().also { it[it.lastIndex] = (it.last().toInt() xor 1).toByte() }
    val corruptArchive = runCatching { repository.inspectBackup(damaged, password) }
    assertTrue(corruptArchive.exceptionOrNull() is AEADBadTagException)

    val preview = repository.inspectBackup(legacy, password)
    repository.commitRenamer = { _, _ -> false }
    try {
      repository.applyBackup(preview)
      throw AssertionError("Expected an injected restore commit failure")
    } catch (_: java.io.IOException) {
      assertEquals(listOf(local), repository.profiles.value)
      assertEquals(listOf(local), open(directory).profiles.value)
      assertArrayEquals(original, snapshot.readBytes())
    }
  }

  private suspend fun assertFixture(
    tag: String,
    repository: DirectoryRepository,
    name: String = "Legacy Contact",
    favourite: Boolean = true,
  ) {
    val profile = checkNotNull(repository.getProfile("legacy-person")) { "$tag lost the original profile ID" }
    assertEquals(tag, name, profile.name)
    assertEquals(tag, "+12025550141", profile.primaryPhone())
    assertEquals(tag, "primary@example.com", profile.primaryEmail())
    val hasLabelledValues = tag == "v1.0.10" || tag == "v1.0.16"
    assertEquals(tag, if (hasLabelledValues) listOf("Office", "Personal") else listOf("Personal"), profile.resolvedPhones().map { it.label })
    assertEquals(tag, if (hasLabelledValues) listOf("primary@example.com", "secondary@example.com") else listOf("primary@example.com"), profile.allEmailValues())
    assertEquals(tag, "Lead", profile.currentPosting()?.designation)
    assertEquals(tag, "introducer", profile.introductions.single().introducerProfileId)
    assertTrue(tag, profile.otherDetails.contains("Foundation Course batch: 101"))
    assertTrue(tag, profile.otherDetails.contains("Training group: Cohort A"))
    assertEquals(tag, favourite, profile.isFavourite)
    assertEquals(tag, listOf("alumni"), profile.tags)
    assertEquals(tag, setOf("legacy-person", "introducer"), repository.groups.value.single().memberIds.toSet())
    assertEquals(tag, "Fixture Owner", repository.ownerCard.value.name)
    assertEquals(tag, false, repository.ownerCard.value.sharePhone)
    assertArrayEquals(
      tag,
      Base64.getDecoder().decode(
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aN8sAAAAASUVORK5CYII=",
      ),
      repository.loadPhotoBytes(checkNotNull(profile.photoFileName)),
    )
  }

  private fun archive(tag: String): ByteArray =
    checkNotNull(javaClass.getResourceAsStream("/compatibility/$tag.nxbk")) { "Missing fixture for $tag" }
      .use { it.readBytes() }

  private fun open(directory: File) = LocalDirectoryRepository(directory, object : LocalStorageCrypto {
    override fun encrypt(plaintext: ByteArray) = plaintext
    override fun decrypt(ciphertext: ByteArray) = ciphertext
  })
}
